import heapq
edges=[('A','B',4),('A','C',1),('C','B',2),('B','D',1),('C','D',5)]
g={}
for u,v,w in edges:
    g.setdefault(u,[]).append((v,w)); g.setdefault(v,[]).append((u,w))
dist={n:float('inf') for n in g}; dist['A']=0
h=[(0,'A')]
while h:
    d,u=heapq.heappop(h)
    if d>dist[u]: continue
    for v,w in g[u]:
        if d+w<dist[v]:
            dist[v]=d+w; heapq.heappush(h,(dist[v],v))
print(dist['D'])

