def make_exporter(kind):
    reg={'csv':lambda xs: ','.join(map(str,xs)),'json':lambda xs: ';'.join(map(str,xs))}
    if kind not in reg: raise ValueError(kind)
    return reg[kind]
print(make_exporter('csv')([1,2,3]))

class Notifier:
    def __init__(self): self.ch=[]
    def subscribe(self,f): self.ch.append(f)
    def notify(self,m):
        for f in self.ch:
            try: f(m)
            except Exception: pass
out=[]
def bad(m): raise RuntimeError('down')
